class Solution { string first,second;set<tuple<int,int,int>> failed;bool dfs(int i,int j,int difference){if(i==(int)first.size()&&j==(int)second.size())return difference==0;auto key=make_tuple(i,j,difference);if(failed.count(key))return false;if(i<(int)first.size()&&isdigit(first[i])){int value=0;for(int end=i;end<(int)first.size()&&end<i+3&&isdigit(first[end]);++end){value=value*10+first[end]-'0';if(dfs(end+1,j,difference+value))return true;}}else if(j<(int)second.size()&&isdigit(second[j])){int value=0;for(int end=j;end<(int)second.size()&&end<j+3&&isdigit(second[end]);++end){value=value*10+second[end]-'0';if(dfs(i,end+1,difference-value))return true;}}else if(difference<0&&i<(int)first.size()&&dfs(i+1,j,difference+1))return true;else if(difference>0&&j<(int)second.size()&&dfs(i,j+1,difference-1))return true;else if(!difference&&i<(int)first.size()&&j<(int)second.size()&&first[i]==second[j]&&dfs(i+1,j+1,0))return true;failed.insert(key);return false;}public: bool possiblyEquals(string s1,string s2){first=s1;second=s2;return dfs(0,0,0);} };
